INSERT INTO public.quizzes (id, subject, unit, title, description) VALUES ('94e03363-0537-475d-8405-64cdb33810ef'::uuid, 'Physics', 'Unit 1', 'Molarum Grade 10 — Physics Vector Quantities', 'Source-grounded Molarum Grade 10 Physics questions for Vector Quantities.') ON CONFLICT (id) DO UPDATE SET subject = EXCLUDED.subject, unit = EXCLUDED.unit, title = EXCLUDED.title, description = EXCLUDED.description;
INSERT INTO public.questions (id, quiz_id, question_type, question_text, correct_answer, explanation, order_index) VALUES ('80b39dc7-2146-4f6e-8f06-b4e2448d7f4c'::uuid, '94e03363-0537-475d-8405-64cdb33810ef'::uuid, 'multiple_choice', 'Which of the following physical quantities is a vector?', 'Velocity', 'Vectors require both magnitude and direction; velocity specifies both.', 0),('88d8c2ba-cc44-4def-8a65-884cf38e0222'::uuid, '94e03363-0537-475d-8405-64cdb33810ef'::uuid, 'multiple_choice', 'In a vector diagram, what does the length of the drawn arrow represent?', 'Magnitude', 'The arrow length is proportional to the vector''s magnitude.', 1),('f54d79bd-a5a8-4c19-899c-3f1432fc0b4a'::uuid, '94e03363-0537-475d-8405-64cdb33810ef'::uuid, 'multiple_choice', 'When adding two vectors graphically, what is the standard head-to-tail method?', 'Place the tail of the second at the head of the first', 'The resultant is drawn from the tail of the first to the head of the second.', 2),('5b685b81-2c44-46d9-82ba-755551d9b796'::uuid, '94e03363-0537-475d-8405-64cdb33810ef'::uuid, 'multiple_choice', 'Two perpendicular vectors have magnitudes 3 N east and 4 N north. The resultant magnitude is?', '5 N', 'Resultant magnitude is sqrt(3^2+4^2)=5 N.', 3),('d718ecd6-a016-4991-8970-7b61de39cbbc'::uuid, '94e03363-0537-475d-8405-64cdb33810ef'::uuid, 'multiple_choice', 'A vector of magnitude 6 N is directed at 60 degrees above the +x axis. Which of the following are its components?', 'Fx = 3 N, Fy ≈ 5.2 N', 'Fx = r cos theta, Fy = r sin theta; with r=6, theta=60°', 4),('e47c5132-275d-4ce2-85bb-869dee84f43a'::uuid, '94e03363-0537-475d-8405-64cdb33810ef'::uuid, 'true_false', 'A vector is completely specified by its magnitude only.', 'False', 'A vector requires both magnitude and direction for complete description.', 5),('152f40ed-e951-47d1-8f79-59853b395a90'::uuid, '94e03363-0537-475d-8405-64cdb33810ef'::uuid, 'fill_blank', 'What is a unit vector and how is it used when resolving a vector into components?', 'A unit vector is a vector with magnitude 1 that points in a given direction. It is used to express a vector as a sum of its components along the coordinate axes, e.g., F = Fx î + Fy ĵ, where Fx = |F| cos(theta) and Fy = |F| sin(theta).', 'Unit vectors provide direction along axes to separate a vector into components.', 6),('6b16f021-c4bb-4def-8137-26849f3e103c'::uuid, '94e03363-0537-475d-8405-64cdb33810ef'::uuid, 'fill_blank', 'List the basic steps of the graphical method of vector addition.', '1) Choose a scale and mark it. 2) Draw each vector tail-to-head in sequence. 3) Draw the resultant from the starting tail to the final head. 4) Measure the resultant’s magnitude and direction.', 'Steps follow the tail-to-head construction; scale ensures accurate representation.', 7),('7e8d21dc-5a3d-489f-8559-401cfa9e542e'::uuid, '94e03363-0537-475d-8405-64cdb33810ef'::uuid, 'fill_blank', 'A displacement vector has magnitude 12 m at 30 degrees north of east. Find its x and y components. Use +x east, +y north.', 'Fx = 10.39 m, Fy = 6.00 m', 'Fx = r cos(theta) = 12 cos(30°) ≈ 10.39 m; Fy = r sin(theta) = 12 sin(30°) = 6.00 m.', 8),('6c1f69c6-fabf-4b6c-8c69-135124d3b170'::uuid, '94e03363-0537-475d-8405-64cdb33810ef'::uuid, 'fill_blank', 'Two vectors A = 8 N at 45° and B = 5 N at 135°. Find the magnitude and direction of the resultant R.', '|R| ≈ 9.43 N; direction ≈ 77.0° above the +x axis', 'Resolve into components: Ax=8cos45≈5.66, Ay=8sin45≈5.66; Bx=5cos135≈-3.54, By=5sin135≈3.54; Rx≈2.12, Ry≈9.19; |R|≈√(Rx^2+Ry^2)≈9.43; θ=atan(Ry/Rx)≈77°.', 9),('1855bf3d-5642-4ad3-8203-4041e31b664f'::uuid, '94e03363-0537-475d-8405-64cdb33810ef'::uuid, 'multiple_choice', 'Which of the following is a vector quantity?', 'Displacement', 'Vectors have both magnitude and direction; displacement specifies a change in position with a direction.', 10),('c0974916-ed76-41f8-85bb-2e2ca47c0947'::uuid, '94e03363-0537-475d-8405-64cdb33810ef'::uuid, 'multiple_choice', 'Which notation represents a vector quantity algebraically?', 'A bold letter such as A or an arrow over A', 'Vectors are represented by a bold letter or an arrow over the letter to indicate direction.', 11),('23fd9c92-fc60-4e2e-821d-9622520ca9f2'::uuid, '94e03363-0537-475d-8405-64cdb33810ef'::uuid, 'multiple_choice', 'If vector A is 3 m east and vector B is 4 m north, their resultant has magnitude and direction approximately:', '5 m at 53.1° north of east', 'Resultant magnitude is sqrt(3^2+4^2)=5 m; angle tanθ = 4/3 ⇒ θ ≈ 53.1° north of east.', 12),('9fd4c560-6c31-4f7d-87c1-aa946fd09ffe'::uuid, '94e03363-0537-475d-8405-64cdb33810ef'::uuid, 'multiple_choice', 'Which method is used to add two vectors graphically?', 'Parallelogram law', 'Graphical addition is often performed using the parallelogram law (head-to-tail approach).', 13),('e82d0616-d499-49ae-828b-e46fc6689da6'::uuid, '94e03363-0537-475d-8405-64cdb33810ef'::uuid, 'multiple_choice', 'A vector A has magnitude 10 N at 60° above the +x axis. Its x- and y-components are:', 'Ax = 5 N, Ay = 8.66 N', 'Ax = 10 cos60° = 5 N; Ay = 10 sin60° ≈ 8.66 N.', 14),('29c442cf-bea1-4cf1-8d94-2025de95ca7f'::uuid, '94e03363-0537-475d-8405-64cdb33810ef'::uuid, 'true_false', 'A scalar quantity has both magnitude and direction.', 'False', 'Scalar quantities have magnitude only; vectors have both magnitude and direction.', 15),('64ba9391-34d1-44d3-8e35-6cb020b28c3b'::uuid, '94e03363-0537-475d-8405-64cdb33810ef'::uuid, 'fill_blank', 'Give two examples of vector quantities and two examples of scalar quantities.', 'Vector: displacement, velocity; Scalar: mass, temperature', 'Vectors require magnitude and direction; scalars require only magnitude and unit.', 16),('76794f93-87c7-436d-8922-ba4bddfd2f43'::uuid, '94e03363-0537-475d-8405-64cdb33810ef'::uuid, 'fill_blank', 'Briefly outline the steps to add two vectors using the head-to-tail (parallelogram) method.', 'Draw both vectors from a common starting point; place the tail of one at the head of the other (head-to-tail); draw the resultant as the diagonal of the parallelogram; measure magnitude and direction using the chosen scale.', 'Head-to-tail method is the graphical approach for vector addition.', 17),('efa420c2-f2a8-4343-83a1-ea71ada8f449'::uuid, '94e03363-0537-475d-8405-64cdb33810ef'::uuid, 'fill_blank', 'A force of 9 N is applied at 40° above the +x axis. Find the x- and y-components (to 2 decimals) and provide the final units.', 'Ax = 6.88 N, Ay = 5.77 N', 'Ax = 9 cos40° ≈ 6.88 N; Ay = 9 sin40° ≈ 5.77 N.', 18),('862991e1-7d62-4d62-8871-1b3e352da3ed'::uuid, '94e03363-0537-475d-8405-64cdb33810ef'::uuid, 'fill_blank', 'Resolve a force of 12 N acting at 60° above the +x axis into x- and y-components.', 'Ax = 6.00 N, Ay = 10.39 N', 'Ax = 12 cos60° = 6.0 N; Ay = 12 sin60° ≈ 10.39 N.', 19),('c2d8bffa-cae8-4063-86f7-bb572d4d453d'::uuid, '94e03363-0537-475d-8405-64cdb33810ef'::uuid, 'multiple_choice', 'Which of the following quantities is a vector?', 'Velocity', 'A vector quantity has both magnitude and direction. Mass, distance, and temperature are scalars with magnitude only.', 20),('69bafa0d-c71b-4455-89e2-b9407ccf4a1a'::uuid, '94e03363-0537-475d-8405-64cdb33810ef'::uuid, 'multiple_choice', 'In a vector diagram drawn to scale, what does the length of the arrow represent?', 'The magnitude', 'In vector diagrams, the length is proportional to the vector''s magnitude; direction is shown by the arrowhead.', 21),('3d3acbcf-8d9b-4596-8c63-838a97794a5b'::uuid, '94e03363-0537-475d-8405-64cdb33810ef'::uuid, 'multiple_choice', 'Which operation corresponds to placing vectors head-to-tail to obtain the resultant?', 'Addition', 'Adding vectors by the head-to-tail method yields the resultant vector.', 22),('409a70e0-c41b-4c5b-8128-05dbbcd84d0c'::uuid, '94e03363-0537-475d-8405-64cdb33810ef'::uuid, 'multiple_choice', 'Resolving a vector into horizontal and vertical components uses which axes?', 'The x- and y-axes', 'Resolving a vector uses horizontal and vertical (x and y) components along the chosen axes.', 23),('ebe699fd-6214-4488-80c2-31272a9552d4'::uuid, '94e03363-0537-475d-8405-64cdb33810ef'::uuid, 'multiple_choice', 'Two equal vectors of 6 N each act with an angle of 60 degrees between them. What is the magnitude of the resultant?', '6√3', 'R = sqrt(A^2 + A^2 + 2A^2 cosθ) with A=6, θ=60 gives R = 6√3 ≈ 10.39 N.', 24),('04782fe2-352a-4a2e-8b47-484b88d3c47e'::uuid, '94e03363-0537-475d-8405-64cdb33810ef'::uuid, 'true_false', 'Displacement and distance are the same when motion is in a straight line with constant direction.', 'True', 'When motion is along a straight line with no direction change, net displacement equals distance travelled.', 25),('2e9ee450-2bb6-4cb9-8751-9c1b06d7736e'::uuid, '94e03363-0537-475d-8405-64cdb33810ef'::uuid, 'fill_blank', 'Name two scalar quantities and two vector quantities.', 'Scalar: mass, temperature; Vector: velocity, force', 'Scalar quantities have only magnitude; vector quantities have magnitude and direction.', 26),('3b17fcea-21f2-4fa4-82db-b3e09b1e2d84'::uuid, '94e03363-0537-475d-8405-64cdb33810ef'::uuid, 'fill_blank', 'Resolve the 70 N force directed 150° from the +x axis into its x and y components.', 'Fx ≈ -60.6 N, Fy ≈ 35.0 N', 'Fx = 70 cos(150°) = -60.6 N; Fy = 70 sin(150°) = 35.0 N.', 27),('c059090d-7515-4b4a-8181-3950fdac22a7'::uuid, '94e03363-0537-475d-8405-64cdb33810ef'::uuid, 'fill_blank', 'Two vectors: A = 30 N directed east; B = 40 N at 60° north of east. Find the resultant magnitude and direction (from +x).', 'R ≈ 60.8 N at ≈ 34.7° north of east', 'Decompose B into components: Bx=40 cos60=20; By=40 sin60≈34.64; R components: Rx=50, Ry=34.64; magnitude ≈ sqrt(50^2+34.64^2) ≈ 60.8 N; direction arctan(34.64/50) ≈ 34.7° north of east.', 28),('16a3006e-8a8a-4d21-8371-bcf0e66f6c5a'::uuid, '94e03363-0537-475d-8405-64cdb33810ef'::uuid, 'fill_blank', 'Resolve a 40 N force acting at 30° above the +x axis into its horizontal (x) and vertical (y) components.', 'Fx ≈ 34.6 N, Fy ≈ 20.0 N', 'Fx = 40 cos30° ≈ 34.64 N; Fy = 40 sin30° = 20.0 N.', 29),('0310f0ba-aa5b-4eaa-8614-54d260f6109e'::uuid, '94e03363-0537-475d-8405-64cdb33810ef'::uuid, 'multiple_choice', 'Which of the following quantities is a vector? (Distinct application example 31.)', 'Velocity', 'A vector has both magnitude and direction; temperature, mass, and time are scalars.', 30),('fce75990-c32b-472e-8fed-0da70da3705d'::uuid, '94e03363-0537-475d-8405-64cdb33810ef'::uuid, 'multiple_choice', 'Which statement correctly describes vector notation?', 'A bold letter denotes a vector quantity or an arrow over the letter indicates a vector; |S| denotes a scalar magnitude.', 'Vectors can be represented by bold letters or with an arrow; |S| gives only magnitude.', 31),('76ff98f3-0baf-4fbb-8c32-8ef924d7c008'::uuid, '94e03363-0537-475d-8405-64cdb33810ef'::uuid, 'multiple_choice', 'A vector diagram is primarily used to show:', 'Both magnitude and direction with an arrow representing the vector', 'Vectors are shown with arrows where length indicates magnitude and direction indicates orientation.', 32),('00702c32-c282-47b4-822c-0f7594c711e2'::uuid, '94e03363-0537-475d-8405-64cdb33810ef'::uuid, 'multiple_choice', 'Which method is used to add two vectors graphically? (Distinct application example 34.)', 'Head-to-tail (tip-to-tail) method', 'Graphical addition places the tail of the second vector at the head of the first; the resulting vector is from tail to head of the two vectors.', 33),('5eb058f1-d361-429a-8c81-e0361cadec08'::uuid, '94e03363-0537-475d-8405-64cdb33810ef'::uuid, 'multiple_choice', 'Which statement is true about resolving a vector into components?', 'A vector can be resolved into horizontal and vertical components using trigonometric projections', 'Components depend on the angle; use cos for horizontal, sin for vertical (assuming angle from x-axis).', 34),('1a31f1d7-23c2-4fc9-859b-57a6d74625a0'::uuid, '94e03363-0537-475d-8405-64cdb33810ef'::uuid, 'true_false', 'Scalars require both magnitude and direction for a complete description.', 'False', 'Scalar quantities have magnitude only; direction is not required for a complete description.', 35),('29d0e01d-4c3f-4f4d-8663-a7084d643918'::uuid, '94e03363-0537-475d-8405-64cdb33810ef'::uuid, 'fill_blank', 'Explain how to resolve a force of 5 N at 30° north of east into horizontal and vertical components.', 'Fx = 5 cos 30° ≈ 4.33 N (east); Fy = 5 sin 30° ≈ 2.50 N (north). The components are found using F cosθ for horizontal and F sinθ for vertical, with angles measured from the +x axis (east).', 'Use standard component resolution: Fx = F cosθ, Fy = F sinθ.', 36),('7d8db22f-81d8-438f-801d-0bc1d510b5cf'::uuid, '94e03363-0537-475d-8405-64cdb33810ef'::uuid, 'fill_blank', 'A boat travels 6.0 km at 20° north of east, then 8.0 km at 60° north of east. Find the magnitude and direction of the resultant displacement.', 'Resultant displacement: components: x = 6 cos20 + 8 cos60 = 5.638 + 4.000 = 9.638 km; y = 6 sin20 + 8 sin60 = 2.052 + 6.928 = 8.980 km. Magnitude ≈ 13.2 km; direction ≈ arctan(8.980/9.638) ≈ 43.6° north of east.', 'Use vector components and Pythagoras to obtain resultant magnitude and arctan for direction.', 37),('231e0667-043b-45f4-80a0-ad50566140de'::uuid, '94e03363-0537-475d-8405-64cdb33810ef'::uuid, 'fill_blank', 'Two displacement vectors A and B have magnitudes 5.0 m and 7.0 m and are at an angle of 40° to each other. What is the magnitude of their resultant displacement? Provide all values, units, and context.', '11.3 m', 'R^2 = A^2 + B^2 + 2AB cos θ; R = sqrt(5^2 + 7^2 + 2*5*7 cos 40°) ≈ sqrt(127.62) ≈ 11.3 m.', 38),('2a9bcf9f-9be2-45a6-8dc0-cb08e135197f'::uuid, '94e03363-0537-475d-8405-64cdb33810ef'::uuid, 'fill_blank', 'Resolve a displacement vector of magnitude 12.0 m directed 25° north of west into its x (horizontal) and y (vertical) components. Provide the components with correct signs and units.', 'Vx ≈ -10.9 m (west); Vy ≈ +5.1 m (north).', 'Vx = 12 cos25° toward west (negative x); Vy = 12 sin25° toward north (positive y).', 39) ON CONFLICT (id) DO UPDATE SET quiz_id = EXCLUDED.quiz_id, question_type = EXCLUDED.question_type, question_text = EXCLUDED.question_text, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, order_index = EXCLUDED.order_index;
